import{_ as a,o as t,c as e,a5 as o}from"./chunks/framework.PLGyiLjE.js";const p=JSON.parse('{"title":"Classes, paths and vows","description":"","frontmatter":{},"headers":[],"relativePath":"guides/paths-and-skills.md","filePath":"guides/paths-and-skills.md"}'),r={name:"guides/paths-and-skills.md"};function n(l,s,i,h,d,g){return t(),e("div",null,[...s[0]||(s[0]=[o('<h1 id="classes-paths-and-vows" tabindex="-1">Classes, paths and vows <a class="header-anchor" href="#classes-paths-and-vows" aria-label="Permalink to &quot;Classes, paths and vows&quot;">​</a></h1><h2 id="four-classes" tabindex="-1">Four classes <a class="header-anchor" href="#four-classes" aria-label="Permalink to &quot;Four classes&quot;">​</a></h2><p>🗡️ <strong>Trailguard:</strong> sword 🏹 <strong>Wayfinder:</strong> bow 🔮 <strong>Runehand:</strong> staff 🌙 <strong>Shadehand:</strong> daggers</p><h2 id="eight-paths" tabindex="-1">Eight paths <a class="header-anchor" href="#eight-paths" aria-label="Permalink to &quot;Eight paths&quot;">​</a></h2><p>When you make your fighter, you pick a class, then one of its two paths, then <strong>Girl</strong> or <strong>Boy</strong>. Your fighter wears that path&#39;s painted look from the start. There are 16 painted fighters in all.</p><ul><li><strong>Bannerguard</strong> (Trailguard): sword and a floating shield, hits hard up close</li><li><strong>Oathblade</strong> (Trailguard): wide sweeps, forge and command hunting swords</li><li><strong>Briar Ranger</strong> (Wayfinder): bow, thorny traps and quick shots</li><li><strong>Flintshot</strong> (Wayfinder): dual pistols, fast shots and ricochets</li><li><strong>Glyphcaster</strong> (Runehand): staff, big blasts of rune fire</li><li><strong>Lightmender</strong> (Runehand): staff, light beams and heals</li><li><strong>Needlehand</strong> (Shadehand): thrown stars, hits from range</li><li><strong>Veildancer</strong> (Shadehand): daggers, fast flurries and dodges</li></ul><h2 id="levels-and-skills" tabindex="-1">Levels and skills <a class="header-anchor" href="#levels-and-skills" aria-label="Permalink to &quot;Levels and skills&quot;">​</a></h2><ul><li>The top level is <strong>50</strong> for now.</li><li>Every level gives <strong>skill points</strong>. <strong>Auto skill points</strong> is on at first and spends them for you. Turn it off in <strong>Character → Skills</strong> to pick your own.</li><li>New skills unlock as you level.</li></ul><h2 id="your-second-vow-lv-30" tabindex="-1">Your second vow (Lv 30) <a class="header-anchor" href="#your-second-vow-lv-30" aria-label="Permalink to &quot;Your second vow (Lv 30)&quot;">​</a></h2><p>At <strong>Lv 30</strong> your path&#39;s shrine in the <strong>Hall of Memories</strong> in Loomhaven glows. Press <strong>Z</strong> there (<strong>G</strong> on WASD keys). You can <strong>Try it</strong> first, then <strong>Take this vow</strong>. The vow is permanent and gives you a Lv 30 weapon and your path&#39;s first Lv 30 skill. At Lv 30 you can also clear <strong>5-4</strong>, then take the vow trial from its results. You need the vow before <strong>5-5</strong> will start.</p><h2 id="later-vows" tabindex="-1">Later vows <a class="header-anchor" href="#later-vows" aria-label="Permalink to &quot;Later vows&quot;">​</a></h2><p>The third vow opens in a later update.</p>',12)])])}const c=a(r,[["render",n]]);export{p as __pageData,c as default};
